def fill_matching(grid):
    R=rects(grid)
    # source: rect whose interior has nonzero cells
    src=None
    for c,(r0,c0,r1,c1) in R.items():
        if any(grid[i][j] for i in range(r0+1,r1) for j in range(c0+1,c1)):
            src=c
    r0,c0,r1,c1=R[src]
    pat=[[grid[i][j] for j in range(c0+1,c1)] for i in range(r0+1,r1)]
    sh,sw=r1-r0+1,c1-c0+1
    res=[row[:] for row in grid]
    for c,(a,b,d,e) in R.items():
        if (d-a+1,e-b+1)==(sh,sw):
            col=c
            for i in range(a+1,d):
                for j in range(b+1,e):
